import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Error codes — the complete numeric surface","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/error-codes.md","filePath":"troubleshooting/error-codes.md"}'),a={name:"troubleshooting/error-codes.md"};function r(s,t,i,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="error-codes-—-the-complete-numeric-surface" tabindex="-1">Error codes — the complete numeric surface <a class="header-anchor" href="#error-codes-—-the-complete-numeric-surface" aria-label="Permalink to &quot;Error codes — the complete numeric surface&quot;">​</a></h1><p>Open Cube OS has <strong>no global <code>errno</code></strong> and no <code>errno.h</code> — the freestanding kernel does not link libc. The universal convention is:</p><ul><li><strong>0 = success, negative = failure</strong> (<code>-1</code> generic; <code>Returns 0 on success, -1 on failure</code> is the documented idiom).</li><li>Subsystems that need precision use <strong>dense negative enums</strong> — 8 families, <strong>61 codes total</strong>, listed below with the trigger and the response for each.</li><li>Sizes/lengths return <code>-1</code>; ring-buffer reads return <code>-1</code> for &quot;past the window&quot;; watchdog slot APIs return <strong>-1 (table full) / -2 (bad arguments)</strong>.</li><li>The one positive sentinel family is the crash-source pseudo-vectors <code>OC_CRASH_SRC_*</code> (32..36), which ride the <code>vector</code> field of crashlog records.</li></ul><p>Commands in this page: <a href="./../manual/commands/dmesg.html">dmesg</a>, <a href="./../manual/commands/logcat.html">logcat</a>, <a href="./../manual/commands/logctl.html">logctl</a>, <a href="./../manual/commands/crashlog.html">crashlog</a>, <a href="./../manual/commands/health.html">health</a>, <a href="./../manual/commands/update.html">update</a>, <a href="./../manual/commands/config.html">config</a>.</p><hr><h2 id="family-1-—-oc-update-e-15-codes-update-pipeline" tabindex="-1">Family 1 — OC_UPDATE_E_* (15 codes, update pipeline) <a class="header-anchor" href="#family-1-—-oc-update-e-15-codes-update-pipeline" aria-label="Permalink to &quot;Family 1 — OC_UPDATE_E_* (15 codes, update pipeline)&quot;">​</a></h2><p>Defined in <code>services/selfhost/interface/svc_selfhost_update.h</code>; decoded to text in <code>svc_selfhost_ab.c</code> / <code>svc_selfhost_update.c</code>. These are the codes behind every <code>update: ... failed: &lt;why&gt;</code> line.</p><table tabindex="0"><thead><tr><th>Code</th><th>Value</th><th>Meaning</th><th>Trigger scenario</th><th>Response</th></tr></thead><tbody><tr><td><code>OC_UPDATE_E_CONFIG</code></td><td>-1</td><td>config file missing or unreadable</td><td><code>/etc/opencube.conf</code> absent on the /etc volume</td><td>check <code>config path</code>; is the /etc volume mounted? See <a href="./storage-issues.html">storage-issues.md</a></td></tr><tr><td><code>OC_UPDATE_E_PREFIX</code></td><td>-2</td><td>invalid URL prefix (must be http:// or https://)</td><td><code>update_url</code> typo (<code>ftp://...</code>)</td><td><code>config get update_url</code>, fix with <code>config set update_url http://...</code></td></tr><tr><td><code>OC_UPDATE_E_DNS</code></td><td>-3</td><td>DNS resolution failed</td><td>the update host does not resolve</td><td><code>dns &lt;host&gt;</code>; check the DNS server from <code>dhcp</code>/<code>ip</code> output</td></tr><tr><td><code>OC_UPDATE_E_CONNECT</code></td><td>-4</td><td>connect failed</td><td>server unreachable (routing/firewall)</td><td><code>ping</code> the host, <code>route</code> shows the gateway, <code>firewall</code> list</td></tr><tr><td><code>OC_UPDATE_E_TIMEOUT</code></td><td>-5</td><td>no response (timeout)</td><td>server accepted nothing</td><td>retry; check host reachability</td></tr><tr><td><code>OC_UPDATE_E_HTTP</code></td><td>-6</td><td>HTTP error</td><td>server returned an error status</td><td>inspect the server side / URL path</td></tr><tr><td><code>OC_UPDATE_E_JSON</code></td><td>-7</td><td>JSON parse failed</td><td>update.json malformed</td><td>fetch it manually with <code>wget</code> and read it</td></tr><tr><td><code>OC_UPDATE_E_BUFSIZE</code></td><td>-8</td><td>response too large</td><td>changes list overflows the 128-byte buffer</td><td>server-side fix (shorten changes)</td></tr><tr><td><code>OC_UPDATE_E_DISABLED</code></td><td>-9</td><td>online_update=no in the config</td><td>update disabled by config</td><td><code>config set online_update yes</code></td></tr><tr><td><code>OC_UPDATE_E_NOAB</code></td><td>-10</td><td>no A/B disk present</td><td>not booted from the A/B layout</td><td><code>update status</code>, then create it: <code>abdisk &lt;dev&gt;</code> (destructive)</td></tr><tr><td><code>OC_UPDATE_E_SHA</code></td><td>-11</td><td>SHA256 verification failed</td><td>corrupted or tampered package</td><td>re-download; check <code>package_sha256</code> in update.json</td></tr><tr><td><code>OC_UPDATE_E_TARGZ</code></td><td>-12</td><td>package is not valid gzip/tar</td><td>truncated download</td><td>re-download; verify size</td></tr><tr><td><code>OC_UPDATE_E_IO</code></td><td>-13</td><td>filesystem I/O error</td><td>/data write failure</td><td><code>df</code>, <code>fsck</code> the volume</td></tr><tr><td><code>OC_UPDATE_E_SLOT</code></td><td>-14</td><td>invalid slot (use A or B)</td><td>internal slot math failed</td><td>run <code>abcfg</code>; report if persistent</td></tr><tr><td><code>OC_UPDATE_E_ARGS</code></td><td>-15</td><td>NULL / malformed arguments</td><td>internal caller bug</td><td>report with the exact command line</td></tr></tbody></table><h2 id="family-2-—-oc-gzip-err-13-codes-incl-0-gunzip" tabindex="-1">Family 2 — OC_GZIP_ERR_* (13 codes incl. 0, gunzip) <a class="header-anchor" href="#family-2-—-oc-gzip-err-13-codes-incl-0-gunzip" aria-label="Permalink to &quot;Family 2 — OC_GZIP_ERR_* (13 codes incl. 0, gunzip)&quot;">​</a></h2><p><code>kernel/core_lib_gzip.h</code> (identical copy in <code>ocse/kernel/lib/lib_gzip.h</code>). Surfaced by the OTA package path and by every gzipped registry program at exec time (app inflation).</p><table tabindex="0"><thead><tr><th>Code</th><th>Value</th><th>Meaning</th><th>Trigger</th><th>Response</th></tr></thead><tbody><tr><td><code>OC_GZIP_ERR_NONE</code></td><td>0</td><td>success</td><td>—</td><td>—</td></tr><tr><td><code>OC_GZIP_ERR_ARGS</code></td><td>-1</td><td>NULL pointer / bad capacity</td><td>API misuse</td><td>internal; report</td></tr><tr><td><code>OC_GZIP_ERR_MAGIC</code></td><td>-2</td><td>not a gzip stream (1f 8b)</td><td>file is not gzip</td><td>re-download / re-compress the package</td></tr><tr><td><code>OC_GZIP_ERR_METHOD</code></td><td>-3</td><td>CM != 8 (deflate)</td><td>non-deflate gzip</td><td>rebuild the package (<code>tools/make_update_pkg.sh</code>)</td></tr><tr><td><code>OC_GZIP_ERR_HEADER</code></td><td>-4</td><td>malformed gzip header</td><td>truncation at the head</td><td>re-download</td></tr><tr><td><code>OC_GZIP_ERR_BLOCK</code></td><td>-5</td><td>invalid block header / length check</td><td>mid-stream corruption</td><td>re-download; verify SHA256 first</td></tr><tr><td><code>OC_GZIP_ERR_TABLE</code></td><td>-6</td><td>invalid Huffman table</td><td>corrupt deflate tables</td><td>as above</td></tr><tr><td><code>OC_GZIP_ERR_DIST</code></td><td>-7</td><td>distance beyond window</td><td>corrupt back-reference</td><td>as above</td></tr><tr><td><code>OC_GZIP_ERR_TRUNC</code></td><td>-8</td><td>stream ended before final block</td><td>truncated tail</td><td>as above</td></tr><tr><td><code>OC_GZIP_ERR_CRC</code></td><td>-9</td><td>CRC32 mismatch in trailer</td><td>silent corruption</td><td>re-download (this is why OC_UPDATE_E_SHA is checked first)</td></tr><tr><td><code>OC_GZIP_ERR_ISIZE</code></td><td>-10</td><td>ISIZE mismatch in trailer</td><td>size field wrong</td><td>as above</td></tr><tr><td><code>OC_GZIP_ERR_SINK</code></td><td>-11</td><td>sink callback failed</td><td>output device errored</td><td>check disk space</td></tr><tr><td><code>OC_GZIP_ERR_STATE</code></td><td>-12</td><td>API misuse (feed after finish, ...)</td><td>caller bug</td><td>internal; report</td></tr></tbody></table><h2 id="family-3-—-oc-tar-err-7-codes-ustar" tabindex="-1">Family 3 — OC_TAR_ERR_* (7 codes, ustar) <a class="header-anchor" href="#family-3-—-oc-tar-err-7-codes-ustar" aria-label="Permalink to &quot;Family 3 — OC_TAR_ERR_* (7 codes, ustar)&quot;">​</a></h2><p><code>kernel/core_lib_tar.h</code> (+ ocse twin). The untar half of package install.</p><table tabindex="0"><thead><tr><th>Code</th><th>Value</th><th>Meaning</th><th>Trigger</th><th>Response</th></tr></thead><tbody><tr><td><code>OC_TAR_ERR_ARGS</code></td><td>-1</td><td>NULL / bad arguments</td><td>API misuse</td><td>internal</td></tr><tr><td><code>OC_TAR_ERR_HEADER</code></td><td>-2</td><td>malformed / short header block</td><td>corrupt archive</td><td>rebuild the package</td></tr><tr><td><code>OC_TAR_ERR_CSUM</code></td><td>-3</td><td>header checksum mismatch</td><td>corrupt header</td><td>rebuild; <code>ustar bad checksum rejected</code> in the fixtures</td></tr><tr><td><code>OC_TAR_ERR_SIZE</code></td><td>-4</td><td>file size field invalid</td><td>non-octal size field</td><td>rebuild</td></tr><tr><td><code>OC_TAR_ERR_SINK</code></td><td>-5</td><td>file callback failed</td><td>target write error</td><td>disk full? <code>df</code></td></tr><tr><td><code>OC_TAR_ERR_STATE</code></td><td>-6</td><td>API misuse</td><td>caller bug</td><td>internal</td></tr><tr><td><code>OC_TAR_ERR_TRUNC</code></td><td>-7</td><td>archive ended mid-entry</td><td>truncated package</td><td>re-download</td></tr></tbody></table><h2 id="family-4-—-oc-config-e-5-codes-etc-opencube-conf" tabindex="-1">Family 4 — OC_CONFIG_E_* (5 codes, /etc/opencube.conf) <a class="header-anchor" href="#family-4-—-oc-config-e-5-codes-etc-opencube-conf" aria-label="Permalink to &quot;Family 4 — OC_CONFIG_E_* (5 codes, /etc/opencube.conf)&quot;">​</a></h2><p><code>kernel/core_lib_config.h</code> (+ ocse twin). Behind <code>config get/set</code> and the config backend.</p><table tabindex="0"><thead><tr><th>Code</th><th>Value</th><th>Meaning</th><th>Trigger</th><th>Response</th></tr></thead><tbody><tr><td><code>OC_CONFIG_E_ARGS</code></td><td>-1</td><td>NULL / bad arguments</td><td>API misuse</td><td>internal</td></tr><tr><td><code>OC_CONFIG_E_NOFILE</code></td><td>-2</td><td>/etc/opencube.conf missing or unreadable</td><td>no /etc volume, or first boot</td><td><code>config path</code>; mount /etc; <code>config restore</code> rebuilds defaults</td></tr><tr><td><code>OC_CONFIG_E_NOKEY</code></td><td>-3</td><td>key not found (or empty value)</td><td>typo&#39;d key</td><td><code>config list</code> shows valid keys</td></tr><tr><td><code>OC_CONFIG_E_TOOLONG</code></td><td>-4</td><td>value does not fit the output buffer</td><td>oversized value</td><td>shorten the value</td></tr><tr><td><code>OC_CONFIG_E_IO</code></td><td>-5</td><td>VFS read/write error</td><td>volume error</td><td><code>fsck</code>, remount</td></tr></tbody></table><h2 id="family-5-—-enc-e-5-codes-gb2312-utf-8-conversion" tabindex="-1">Family 5 — ENC_E_* (5 codes, GB2312/UTF-8 conversion) <a class="header-anchor" href="#family-5-—-enc-e-5-codes-gb2312-utf-8-conversion" aria-label="Permalink to &quot;Family 5 — ENC_E_* (5 codes, GB2312/UTF-8 conversion)&quot;">​</a></h2><p><code>services/encoding/interface/svc_encoding_core.h</code> (+ ocse twin). Used by the CJK console layer and <code>serial_encoding</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>Value</th><th>Meaning</th><th>Trigger</th><th>Response</th></tr></thead><tbody><tr><td><code>ENC_E_INVAL</code></td><td>-2</td><td>NULL pointer / zero capacity</td><td>API misuse</td><td>internal</td></tr><tr><td><code>ENC_E_TRUNC</code></td><td>-3</td><td>input ends mid-sequence</td><td>truncated multibyte input</td><td>check the sender&#39;s encoding (<code>serial_encoding</code>)</td></tr><tr><td><code>ENC_E_ILLEGAL</code></td><td>-4</td><td>byte sequence not valid in the charset</td><td>GBK bytes read as UTF-8 or vice versa</td><td><code>serial_encoding utf8|gbk</code> to match the peer</td></tr><tr><td><code>ENC_E_NOSPACE</code></td><td>-5</td><td>output buffer too small</td><td>huge conversion</td><td>internal</td></tr><tr><td><code>ENC_E_UNMAP</code></td><td>-6</td><td>codepoint has no mapping in the target</td><td>rare hanzi without GB2312 mapping</td><td>unavoidable; the font layer falls back</td></tr></tbody></table><h2 id="family-6-—-x509-e-8-codes-ok-certificate-verification" tabindex="-1">Family 6 — X509_E_* (8 codes + OK, certificate verification) <a class="header-anchor" href="#family-6-—-x509-e-8-codes-ok-certificate-verification" aria-label="Permalink to &quot;Family 6 — X509_E_* (8 codes + OK, certificate verification)&quot;">​</a></h2><p><code>services/crypto/interface/svc_crypto_x509.h</code>; decoded in <code>svc_crypto_x509.c</code>. These decide whether HTTPS connections live.</p><table tabindex="0"><thead><tr><th>Code</th><th>Value</th><th>Meaning</th><th>Trigger</th><th>Response</th></tr></thead><tbody><tr><td><code>X509_OK</code></td><td>0</td><td>verified</td><td>chain anchored in the embedded root store (ISRG Root X1 etc.)</td><td>—</td></tr><tr><td><code>X509_E_FORMAT</code></td><td>-1</td><td>bad certificate format</td><td>malformed DER</td><td>server-side fix</td></tr><tr><td><code>X509_E_UNSUPPORTED</code></td><td>-2</td><td>unsupported algorithm</td><td>non-RSA chain</td><td>server-side fix</td></tr><tr><td><code>X509_E_EXPIRED</code></td><td>-3</td><td>certificate expired</td><td>stale server cert</td><td><code>rtc</code> (is the guest clock sane?); then server-side</td></tr><tr><td><code>X509_E_NOT_YET</code></td><td>-4</td><td>certificate not yet valid</td><td>clock in the past</td><td><code>rtc</code></td></tr><tr><td><code>X509_E_NO_ROOT</code></td><td>-5</td><td>issuer certificate missing</td><td>self-signed or unanchored chain</td><td>REFUSED by default (the security model); explicit opt-in only via <code>config set tls.insecure 1</code> for testing</td></tr><tr><td><code>X509_E_BADSIG</code></td><td>-6</td><td>signature verification failed</td><td>tampered cert</td><td>treat as hostile; do not bypass</td></tr><tr><td><code>X509_E_HOSTNAME</code></td><td>-7</td><td>hostname mismatch</td><td>cert for another name</td><td>fix the URL or the cert</td></tr><tr><td><code>X509_E_NO_ISSUER</code></td><td>-8</td><td>(reserved/unknown)</td><td>decode-table fallback prints <code>unknown error</code></td><td>report</td></tr></tbody></table><h2 id="family-7-—-oc-usb-e-7-codes-usb-transfers" tabindex="-1">Family 7 — OC_USB_E* (7 codes, USB transfers) <a class="header-anchor" href="#family-7-—-oc-usb-e-7-codes-usb-transfers" aria-label="Permalink to &quot;Family 7 — OC_USB_E* (7 codes, USB transfers)&quot;">​</a></h2><p><code>drivers/usb/drv_usb_core.h</code> (+ ocse twin). Every USB transfer returns one of these.</p><table tabindex="0"><thead><tr><th>Code</th><th>Value</th><th>Meaning</th><th>Trigger</th><th>Response</th></tr></thead><tbody><tr><td><code>OC_USB_ETIMEDOUT</code></td><td>-100</td><td>transfer timed out</td><td>stalled device</td><td>replug; <code>usb</code> to re-enumerate</td></tr><tr><td><code>OC_USB_ENODEV</code></td><td>-101</td><td>no device</td><td>device detached</td><td>replug; <code>usb_hotplug_test</code> reproduces detach path</td></tr><tr><td><code>OC_USB_ESTALL</code></td><td>-102</td><td>endpoint stalled</td><td>device refused the request</td><td>device-side; <code>usb_storage_test</code> shows CSW state</td></tr><tr><td><code>OC_USB_EIO</code></td><td>-103</td><td>I/O error</td><td>bus error</td><td>check the controller (<code>usb</code>, <code>lspci</code>)</td></tr><tr><td><code>OC_USB_ENOMEM</code></td><td>-104</td><td>out of memory</td><td>allocation failure</td><td><code>mem</code>/<code>free</code>; report</td></tr><tr><td><code>OC_USB_EINVAL</code></td><td>-105</td><td>invalid argument</td><td>API misuse</td><td>internal</td></tr><tr><td><code>OC_USB_ENAK</code></td><td>-106</td><td>NAK (not ready yet)</td><td>device busy</td><td>retry</td></tr></tbody></table><h2 id="family-8-—-oc-power-e-unsupported-1-code" tabindex="-1">Family 8 — OC_POWER_E_UNSUPPORTED (1 code) <a class="header-anchor" href="#family-8-—-oc-power-e-unsupported-1-code" aria-label="Permalink to &quot;Family 8 — OC_POWER_E_UNSUPPORTED (1 code)&quot;">​</a></h2><p><code>services/power/interface/svc_power_core.h</code> (+ ocse twin): <code>-1</code> — &quot;machine still running after all ports&quot;. Returned when the power-off walk tried every port (ACPI S5, port 0x64, CF9) and the machine is still alive; the user sees <code>Power off not supported. System halted.</code> — use the host&#39;s power control in a VM.</p><h3 id="decoded-text-tables-where-the-strings-live" tabindex="-1">Decoded text tables (where the strings live) <a class="header-anchor" href="#decoded-text-tables-where-the-strings-live" aria-label="Permalink to &quot;Decoded text tables (where the strings live)&quot;">​</a></h3><p>Each family has a twin decode-to-text table next to the call site — the natural grep anchors: <code>svc_selfhost_ab.c</code> (update), <code>svc_crypto_x509.c</code> (x509), the <code>put()</code> strings in the fs/block/net services. The SMBus i801 status words decode to <code>NACK/device error</code>, <code>bus error/collision</code>, <code>transaction failed</code>, <code>timeout</code>.</p><hr><h2 id="the-11-kernel-panic-call-sites" tabindex="-1">The 11 kernel_panic call sites <a class="header-anchor" href="#the-11-kernel-panic-call-sites" aria-label="Permalink to &quot;The 11 kernel_panic call sites&quot;">​</a></h2><p>Panic reasons are <strong>composed</strong>, not literal (built with strcpy/strcat/u64_to_str on a stack buffer), so grep for the constant prefix, not the whole string.</p><table tabindex="0"><thead><tr><th>#</th><th>Site</th><th>Reason string (format)</th><th>Trigger</th></tr></thead><tbody><tr><td>1</td><td><code>arch_exceptions.c:203</code></td><td>passthrough <code>&lt;reason&gt;</code></td><td>the arch fallback used when the crash service is not yet registered — prints <code>KERNEL PANIC (no crash handler installed): &lt;reason&gt;</code> + <code>System halted.</code></td></tr><tr><td>2</td><td><code>core_sched.c:658</code></td><td><code>kernel stack bounds violated on switch (task=&lt;name&gt;, rsp=0x&lt;hex&gt; window=[0x&lt;lo&gt;,0x&lt;hi&gt;])</code></td><td>the scheduler is about to switch to a task whose saved RSP is outside its stack window (corruption/overflow); it refuses to resume on foreign memory</td></tr><tr><td>3</td><td><code>svc_crash_core.c:563</code></td><td><code>watchdog timeout: no heartbeat for &lt;N&gt;s (task=&lt;name&gt;)</code></td><td>the software crash-watchdog saw no heartbeat for OC_WDT_TIMEOUT_MS (15 s default; armed only after boot, tick registered but DISARMED by default to avoid false panics during long shell commands)</td></tr><tr><td>4</td><td><code>svc_crash_watchdog.c:451</code></td><td><code>watchdog timeout: &lt;N&gt;s without a feed (task=&lt;name&gt;)</code></td><td>a registered watchdog slot with policy PANIC exceeded its budget (e.g. <code>watchdog test panic</code>)</td></tr><tr><td>5</td><td><code>svc_diag_l1.c:261</code></td><td><code>manual crashtest: kernel_panic()</code></td><td>the <code>crashtest panic</code> command</td></tr><tr><td>6</td><td><code>ocse/core_watchdog.c:450</code></td><td>(twin of #4)</td><td>OCSE installer kernel watchdog</td></tr><tr><td>7</td><td><code>ocse/core_sched.c:613</code></td><td>(twin of #2)</td><td>OCSE scheduler</td></tr><tr><td>8</td><td><code>ocse/core_crash.c:567</code></td><td><code>watchdog timeout: no shell heartbeat for &lt;N&gt;s</code></td><td>OCSE soft watchdog</td></tr><tr><td>9</td><td><code>arch_exceptions.c:438+</code> (ocos)</td><td><code>KERNEL STACK OVERFLOW (guard page hit, task=&lt;name&gt;)</code></td><td>#PF whose CR2 is inside a kthread guard page</td></tr><tr><td>10</td><td>(twin)</td><td><code>KERNEL STACK OVERFLOW (stack exhausted -&gt; #DF, task=&lt;name&gt;)</code></td><td>#DF with RSP at/below the task stack base or ≥ 0x40000000000</td></tr><tr><td>11</td><td>(both trees)</td><td><code>ring-0 exception &lt;N&gt; (&lt;#XX Name&gt;)</code></td><td>any other unhandled ring-0 exception</td></tr></tbody></table><p>Banner-only halts (no panic record): <code>PANIC: idle task stack allocation failed - halting</code> (sched init OOM — both kernels).</p><h3 id="the-unified-panic-banner-what-prints-in-order" tabindex="-1">The unified panic banner (what prints, in order) <a class="header-anchor" href="#the-unified-panic-banner-what-prints-in-order" aria-label="Permalink to &quot;The unified panic banner (what prints, in order)&quot;">​</a></h3><p>On serial (authoritative) + VGA (best effort):</p><ol><li><code>*** NESTED PANIC INSIDE PANIC - HALTING ***</code> — one line, then halt (never recurses).</li><li>#DF special case: <code>*** KERNEL PANIC: &lt;reason&gt; [task=&lt;name&gt;] ***</code> + <code>source: #DF Double Fault err=0x&lt;hex&gt; rip=0x&lt;hex&gt; handled at dispatcher depth]</code> + <code>core dump: skipped in #DF mode (see KNOWN_ISSUES)</code> + policy line.</li><li>CR3 normalization; klog ring FATAL record; crashlog record (no text).</li><li><code>*** KERNEL PANIC: &lt;reason&gt; ***</code> (+ <code> [KERNEL STACK OVERFLOW: exhausted, task=&lt;name&gt;]</code> annotation) + kernel version/build + source line (<code>manual/panic|watchdog-timeout|assertion-failed|contained(TUI)| kstack-overflow|exception &lt;N&gt;</code>) + task + registers + traceback.</li><li>VGA one-liner (reason truncated to 90 chars) + <code>Registers and call trace on the serial console.</code></li><li>Core dump status: <code>core dump: UNAVAILABLE (no boot-time buffer)</code> or <code>&lt;N&gt; bytes captured, persisted to /var/crash/core.dump</code> (or serial fallback / <code>persist FAILED</code>).</li><li>L1 panic-handler chain: <code>*** panic handler claimed recovery - resuming ***</code> (rare — the TUI crash guard is the one user).</li><li>Log flush status: <code>crash log: &lt;n&gt; bytes to /var/log/crash.log; klog flushed &lt;n&gt; bytes to /var/log/kernel.log</code> (or FAILED variants).</li><li>Policy: <code>policy: HALT|REBOOT - system stopped (safe halt loop)| - rebooting NOW</code>.</li></ol><h3 id="crash-source-pseudo-names-crashlog-vector-field-32-36" tabindex="-1">Crash-source pseudo-names (crashlog <code>vector</code> field 32..36) <a class="header-anchor" href="#crash-source-pseudo-names-crashlog-vector-field-32-36" aria-label="Permalink to &quot;Crash-source pseudo-names (crashlog `vector` field 32..36)&quot;">​</a></h3><p><code>manual/panic</code>, <code>watchdog-timeout</code>, <code>assertion-failed</code>, <code>contained(TUI)</code>, <code>kstack-overflow</code>, fallback <code>exception</code>. The x86 vector names in records: <code>#DE Divide Error</code>, <code>#DB Debug</code>, <code>#BP Breakpoint</code>, <code>#OF Overflow</code>, <code>#BR Bound Range Exceeded</code>, <code>#UD Invalid Opcode</code>, <code>#NM Device Not Available</code>, <code>#DF Double Fault</code>, <code>#TS Invalid TSS</code>, <code>#NP Segment Not Present</code>, <code>#SS Stack-Segment Fault</code>, <code>#GP General Protection</code>, <code>#PF Page Fault</code>, <code>#MF x87 FPU Error</code>, <code>#AC Alignment Check</code>, <code>#MC Machine Check</code>, <code>#XM SIMD FP Exception</code>, <code>#SX Security Exception</code>, fallback <code>Unknown</code>.</p><hr><h2 id="the-30-static-assert-guards" tabindex="-1">The 30 <code>_Static_assert</code> guards <a class="header-anchor" href="#the-30-static-assert-guards" aria-label="Permalink to &quot;The 30 `_Static_assert` guards&quot;">​</a></h2><p>All compile-time layout contracts — a drift <strong>fails the build</strong>, never the runtime. If you hit one, the two sides of a cross-module ABI stopped agreeing:</p><table tabindex="0"><thead><tr><th>Guard</th><th>Where</th><th>Contract</th></tr></thead><tbody><tr><td><code>ocst_u32 must be 4 bytes</code> / <code>ocst_state_t layout drifted</code> / <code>ocst_record_t layout drifted</code></td><td><code>include/ocbl_state.h</code></td><td>the OCBL↔OCOS↔OCIRE cross-boot mailbox (0x98000/0x9B000)</td></tr><tr><td><code>regs struct layout drift</code></td><td><code>ocbl/bios/ocbl_bios.h</code></td><td>BIOS register frame</td></tr><tr><td><code>ehdr layout</code> / <code>phdr layout</code></td><td><code>ocbl/common/ocbl_load.c</code></td><td>ELF headers OCBL parses</td></tr><tr><td><code>task_t.fpu_state offset must match OFF_FPU in arch_context_switch.S</code> (+ <code>fpu_saved</code>, <code>rflags</code> twins)</td><td><code>ocos/core_sched.c</code> <strong>and</strong> <code>ocse/core_sched.c</code> (3 each)</td><td>scheduler↔asm context-switch ABI</td></tr><tr><td><code>registry empty</code></td><td><code>ocos/core_usermode.c</code></td><td>the app registry compiled in</td></tr><tr><td><code>chinese_font gz layout mismatch - regenerate chinese_font_data.c</code></td><td><code>services/font/svc_font_chinese.c</code></td><td>the embedded CJK font blob</td></tr><tr><td>8 UHCI schedule-page overlap guards: <code>ISO TD overlaps int QH</code>, <code>int QH overlaps ctrl QH</code>, <code>ctrl QH overlaps ctrl TDs</code>, <code>ctrl TD pool overlaps bulk QH</code>, <code>bulk QH overlaps bulk TDs</code>, <code>bulk TD pool overlaps int TDs</code>, <code>int TD pool overlaps scratch</code>, <code>scratch overflows schedule page</code></td><td><code>drivers/usb/drv_usb_core.c</code> <strong>and</strong> the ocse twin (8 each)</td><td>the UHCI frame-list layout math</td></tr></tbody></table><hr><h2 id="log-formats-—-reading-the-output" tabindex="-1">Log formats — reading the output <a class="header-anchor" href="#log-formats-—-reading-the-output" aria-label="Permalink to &quot;Log formats — reading the output&quot;">​</a></h2><h3 id="klog-dmesg-logcat" tabindex="-1">klog (dmesg / logcat) <a class="header-anchor" href="#klog-dmesg-logcat" aria-label="Permalink to &quot;klog (dmesg / logcat)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[&lt;seconds&gt;.&lt;mmm padded to 3&gt;] &lt;LEVEL padded to 6&gt; &lt;module&gt;: &lt;message&gt;</span></span></code></pre></div><p>Example: <code>[ 12.345] ERROR watchdog: watchdog slot 3 (net-rx) -&gt; KILL task</code>.</p><p>Levels: <code>DEBUG</code> 0, <code>INFO</code> 1, <code>WARN</code> 2, <code>ERROR</code> 3, <code>FATAL</code> 4. The ring holds 1024 entries; overwrites are counted into <code>klog_dropped()</code> and <code>dmesg</code> shows the footer <code>-- &lt;shown&gt; lines (ring &lt;n&gt;/1024, dropped &lt;d&gt;) --</code>. Filter with <code>logcat -l &lt;level&gt;</code> (debug..fatal or 0-4), <code>-m &lt;module&gt;</code>, <code>-k &lt;keyword&gt;</code>, <code>-t &lt;seconds&gt;</code>, <code>-n &lt;count&gt;</code>; follow with <code>-f</code>. See <a href="./silent-failures.html">silent-failures.md</a> for level-filtering traps.</p><h3 id="boot-stage-log" tabindex="-1">Boot stage log <a class="header-anchor" href="#boot-stage-log" aria-label="Permalink to &quot;Boot stage log&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[HH:MM:SS.mmm] &lt;stage&gt;: OK|FAIL</span></span></code></pre></div><p>Quiet level 1 suppresses non-FAIL lines; any <code>FAIL</code> substring marks a failure for the boot-state judge. Stage names (the OCST ladder): <code>BOOT</code>, <code>KM_AIN_ENTERED</code>, <code>SCHED_READY</code>, <code>DRIVERS_READY</code>, <code>SERVICES_READY</code>, <code>L1_LAUNCHED</code>, <code>L1_READY</code>, runtime marker 255 = <code>RUNTIME</code>.</p><h3 id="health-alarms-klog-warn-class" tabindex="-1">Health alarms (klog WARN class) <a class="header-anchor" href="#health-alarms-klog-warn-class" aria-label="Permalink to &quot;Health alarms (klog WARN class)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alarm: memory &gt;90% used (&lt;used&gt;/&lt;total&gt; KiB)</span></span>\n<span class="line"><span>alarm: &lt;n&gt; active tasks (&gt;64)</span></span>\n<span class="line"><span>alarm: CPU &gt;=90% busy for 10 consecutive seconds</span></span></code></pre></div><p>The <code>health</code> command is the first thing to run when the machine &quot;feels wrong&quot; — see <a href="./silent-failures.html">silent-failures.md</a>.</p><h3 id="crash-records" tabindex="-1">Crash records <a class="header-anchor" href="#crash-records" aria-label="Permalink to &quot;Crash records&quot;">​</a></h3><p><code>crashlog</code> lists the 32-entry ring (fields: jiffies, rtc_epoch, vector, ring, error_code, rip, rsp, cr2, tid, pid, task[16]); flushed to <code>/var/log/crash.log</code>; core dumps land in <code>/var/crash/core.dump</code>; klog flushes to <code>/var/log/kernel.log</code>.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./error-catalog.html">error-catalog.md</a> — every message string by subsystem, with investigation chains</li><li><a href="./silent-failures.html">silent-failures.md</a> — failures that print nothing at all</li><li><a href="./../manual/hidden-commands.html">../manual/hidden-commands.md</a> — the test stubs that exercise these paths on purpose</li><li><a href="./../arch/crash-recovery.html">../arch/crash-recovery.md</a> — the panic machinery design</li></ul>',60)])])}const g=e(a,[["render",r]]);export{p as __pageData,g as default};
